describe('Task Creation', () => {
    beforeEach(() => {
        cy.visit('/tasks/new');
    });

    it('should create a new task successfully', () => {
        cy.get('input[name="taskName"]').type('New Task');
        cy.get('textarea[name="taskDescription"]').type('This is a description for the new task.');
        cy.get('input[name="dueDate"]').type('2023-12-31');
        cy.get('button[type="submit"]').click();

        cy.url().should('include', '/tasks');
        cy.contains('New Task').should('be.visible');
        cy.contains('This is a description for the new task.').should('be.visible');
    });

    it('should show an error when required fields are not filled', () => {
        cy.get('button[type="submit"]').click();

        cy.get('.error-message').should('be.visible');
        cy.get('.error-message').should('contain', 'Task name is required');
        cy.get('.error-message').should('contain', 'Task description is required');
    });
});
